import "server-only";
import QRCode from "qrcode";

/**
 * QR as an inline SVG string (only paths generated by the library, safe to inline).
 * Never the smallest size (version 1, 21×21): the ZXing reader that iPhones fall back to
 * almost never locates it, while version 2 (25×25) reads reliably. Longer text gets the
 * size it needs automatically.
 */
export async function qrSvg(text: string, margin = 0) {
  const opts = { type: "svg", margin, errorCorrectionLevel: "M" } as const;
  try {
    return await QRCode.toString(text, { ...opts, version: 2 });
  } catch {
    return QRCode.toString(text, opts);
  }
}
